  const dueValue = options.get("--due");
  const database = await loadDatabase();
  const task: Task = {
    id: database.nextId,
    title,
    status: "open",
    createdAt: new Date().toISOString(),
    tags: normalizeTags(options.get("--tags") ?? ""),
